head.script:
scwin.trigger1_onclick = function(e) {
    group1.setDisabled(true);
};
scwin.isDisable = function() {
    var el = WebSquare.wUnit.getDomById($p.id + "gridView1_dataLayer");
    return el.classList.contains('w2grid_disabled');
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 하단의 'setDisabled'버튼을 클릭한다. 
    //1. Run the sample file and click the 'setDisabled' button at the bottom.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    // verify step1. group 하위에 있는 컴포넌트들이 모두 disabled 처리되어진다.(상단 그룹하위 비활성화됨)(이전에는 disabled 되지 않음)
    //1. All the components under group are disabled (the top group sub is disabled).(Previously not disabled) 
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input1').getDisabled()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.isDisable()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test
    WebSquare.wUnit.run();
    //stop
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    dataList1.setData([1, 1, 2, 2, 3, 3, 4, 4]);
    input1.setValue("55555");
    //Function unitTest
    //Created By: Sang.do
    //Created By: 19-Jan-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
